                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                     end if
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  deallocate(sidx)
                  deallocate(pidx)
                  deallocate(vbbb13_amps,vbbb13_excits,key_vbbb13,off_vbbb13)
                  deallocate(bt4d_amps,bt4d_excits)
                  deallocate(bt4e_amps,bt4e_excits)
                  call release_sort_workspace()
              end subroutine t4e_p_b2_chol

end module ccsdtq_p_t4e_p_b2_chol
